'use strict';
// VAGANCIA FITNESS: an independent interface concept. All device telemetry is simulated.
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const uid = () => 'id-' + Date.now().toString(36) + Math.random().toString(36).slice(2,8);
const clone = value => JSON.parse(JSON.stringify(value));
const glyphs = {
 home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
 programs:'M4 4h16v16H4zM8 8h8M8 12h8M8 16h5',
 activity:'M3 12h4l3-8 4 16 3-8h4',
 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 3 2 3v4l4 1 3 3 3-3 4-1v-4l2-3-2-3-3-1-1-3Z',
 arrow:'m9 5 7 7-7 7', back:'m15 5-7 7 7 7', plus:'M12 5v14M5 12h14', close:'m6 6 12 12M6 18 18 6',
 play:'m8 4 12 8-12 8Z', pause:'M8 5v14M16 5v14', stop:'M6 6h12v12H6Z',
 bluetooth:'m7 7 10 10-5 4V3l5 4L7 17', heart:'M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-4 4 0 9 8 15 8-6 12-11 8-15Z',
 clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18', edit:'m15 4 5 5M4 20l5-1L21 7l-4-4L5 15Z',
 copy:'M8 8h13v13H8zM16 8V3H3v13h5', trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',
 up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6', check:'m5 12 4 4L19 6', download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
 minus:'M5 12h14', bolt:'m13 2-9 12h7l-1 8L20 9h-7Z', shield:'M12 3 3 7v6c0 4 9 8 9 8s9-4 9-8V7ZM8 12l3 3 5-6',
 run:'M14 4a1 1 0 1 0 2 0 1 1 0 0 0-2 0M5 9l5-2 4 4 5 1M10 7l-1 7-5 5M9 14l6 1 2 6',
 infinity:'M12 12C4-1-4 25 12 12s24-13 0 0', more:'M5 12h.01M12 12h.01M19 12h.01'
};
const icon = (name, extra='') => `<svg class="od-icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[name] || glyphs.activity}"/></svg>`;
const fmt = (number, digits=1) => Number(number).toLocaleString('es-CR',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const time = seconds => `${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`;
const date = value => new Date(value).toLocaleDateString('es-CR',{day:'numeric',month:'long'});
const kinds = {warm:'Calentamiento',work:'Esfuerzo',recover:'Recuperación',cool:'Enfriamiento'};
const baseIntervals = [[120,5,'warm'],[90,9,'work'],[150,5,'recover'],[90,10,'work'],[150,5,'recover'],[90,10,'work'],[150,5,'recover'],[90,10,'work'],[150,4,'cool']].map(([seconds,speed,kind])=>({id:uid(),seconds,speed,incline:0,kind}));
const defaults = {
 programs:[{id:'essential',name:'Intervalos esenciales',description:'Alterna esfuerzo y recuperación.',intervals:baseIntervals},{id:'steady',name:'A tu ritmo',description:'Una caminata continua, sin prisa.',intervals:[{id:uid(),seconds:180,speed:4,incline:0,kind:'warm'},{id:uid(),seconds:1200,speed:5.5,incline:1,kind:'work'},{id:uid(),seconds:120,speed:4,incline:0,kind:'cool'}]}],
 sessions:[{id:'sample',name:'Carrera por intervalos',date:'2026-10-15T12:44:00-06:00',seconds:1929,distance:3.61,calories:253,steps:3988,heart:135,maxHeart:175,averageSpeed:6.7,maxSpeed:14.4,demo:true,samples:[4,5,7,5,9,5,10,5,12,5,14.4,5,9,5,4]}],connected:false
};
const STORAGE_KEY='vagancia-fitness-v1';
const PREVIOUS_STORAGE_KEY='fitness-open-v1';
const LEGACY_STORAGE_KEY='fitshow-open-v1';
let stored, storageAvailable=true;
// Read the earlier project key as a fallback so the brand change keeps existing data.
try { stored=JSON.parse(localStorage.getItem(STORAGE_KEY)||localStorage.getItem(PREVIOUS_STORAGE_KEY)||localStorage.getItem(LEGACY_STORAGE_KEY)||'null'); } catch {storageAvailable=false;}
let data=stored&&stored.version===1&&Array.isArray(stored.programs)&&Array.isArray(stored.sessions)?stored:clone(defaults);
let route='home', selectedId=data.programs[0]?.id, selectedSession=null, draft=null, running=null, lastPage='home', sheetFocus=null, toastTimer, filter='all';
const app=$('#app');
const scrollPositions={};let lastRenderedRoute=null,sheetResumeState=null;
const total = p => p.intervals.reduce((sum,x)=>sum+x.seconds,0);
const estimated = p => p.intervals.reduce((sum,x)=>sum+x.speed*x.seconds/3600,0);
const program = () => data.programs.find(p=>p.id===selectedId);
function persist(){ try {localStorage.setItem(STORAGE_KEY,JSON.stringify({...data,version:1}));} catch {storageAvailable=false;toast('No hay almacenamiento disponible. Los cambios duran esta visita.');} }
function toast(message){ const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3800); }
function navigate(next, {back=false}={}){scrollPositions[route]=$('.page-scroll')?.scrollTop||0;if(!back)lastPage=route;route=next;render();const scroll=$('.page-scroll');if(scroll)scroll.scrollTop=back?(scrollPositions[next]||0):0;$('.page-title')?.focus({preventScroll:true});}
function navFooter(active){return `<nav class="tabbar" aria-label="Navegación principal">${[['home','home','Inicio'],['programs','programs','Programas'],['activity','activity','Actividad'],['settings','settings','Ajustes']].map(([id,g,label])=>`<button class="tab ${active===id?'selected':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}>${icon(g)}<span>${label}</span></button>`).join('')}</nav>`;}
function topbar(title,{back=false,action=''}={}){return `<header class="topbar od-row">${back?`<button class="icon-button" data-action="back" aria-label="Volver">${icon('back')}</button>`:''}<span class="topbar-title od-fill">${title}</span>${action}</header>`;}
function stat(value,label,unit=''){return `<div class="od-stat"><strong class="stat-value od-nowrap">${value}${unit?` <small>${unit}</small>`:''}</strong><span class="stat-label">${label}</span></div>`;}
function intervalChart(intervals,large=false){return `<div class="interval-chart ${large?'large':''}" role="img" aria-label="Perfil de velocidad: ${esc(intervals.map(x=>`${kinds[x.kind]}, ${fmt(x.speed)} kilómetros por hora, ${time(x.seconds)}`).join('; '))}">${intervals.map(x=>`<span class="interval-bar ${x.kind}" style="--bar-height:${Math.max(16,x.speed/16*100)}%;--bar-weight:${x.seconds}"></span>`).join('')}</div>`;}
function programRow(p){return `<button class="program-row od-row" data-program="${esc(p.id)}"><span class="program-symbol">${icon(p.id==='steady'?'run':'programs')}</span><span class="od-field od-fill"><strong class="od-truncate">${esc(p.name)}</strong><span class="muted">${fmt(total(p)/60,0)} min · ${p.intervals.length} intervalos</span></span>${icon('arrow','chevron')}</button>`;}
function home(){const p=data.programs[0];const s=data.sessions;const minutes=Math.round(s.reduce((v,x)=>v+x.seconds,0)/60);return `${topbar(`<span class="wordmark"><img class="brand-mark" src="./assets/vagancia-fitness-mark.svg" width="96" height="96" alt="" aria-hidden="true"><span class="brand-name">VAGANCIA <span class="brand-fitness">FITNESS</span></span></span>`,{action:`<button class="icon-button profile" data-nav="settings" aria-label="Abrir ajustes">${icon('settings')}</button>`})}<div class="page-scroll od-scroll home-page"><div class="heading-block"><div class="od-row od-fill"><p class="muted date-label">Jueves, 15 de octubre</p><span class="sample-label">Demo</span></div><h1 class="page-title" tabindex="-1">Cada paso<br>cuenta.</h1><p class="intro">Entrena a tu ritmo. Tú tienes el control.</p></div>
<button class="device-strip od-row" data-action="device"><span class="device-icon">${icon('bluetooth')}</span><span class="od-field od-fill"><strong>${data.connected?'Equipo de demo conectado':'Conecta tu equipo'}</strong><span class="muted">${data.connected?'Listo para una sesión simulada':'Prueba una conexión simulada'}</span></span>${icon('arrow','chevron')}</button>
<div class="section-heading od-row"><h2 class="od-fill">Tu próxima sesión</h2><button class="text-button" data-nav="programs">Ver todo ${icon('arrow')}</button></div>
${p?`<article class="featured"><h3>${esc(p.name)}</h3>${intervalChart(p.intervals)}<div class="od-row feature-bottom"><div class="od-field od-fill"><strong>${fmt(total(p)/60,0)} min</strong><span>${p.intervals.length} intervalos · ${fmt(estimated(p),2)} km aprox.</span></div><button class="round-play" data-program="${esc(p.id)}" aria-label="Ver ${esc(p.name)}">${icon('play')}</button></div></article>`:`<div class="empty"><h3>Tu primera sesión empieza aquí.</h3><button class="btn-pill" data-action="new">Crear programa</button></div>`}
<div class="section-heading od-row"><h2 class="od-fill">Tu actividad</h2><button class="text-button" data-nav="activity">Ver más ${icon('arrow')}</button></div><div class="activity-overview"><div class="od-row"><div class="od-stat od-fill"><strong class="overview-number od-nowrap">${minutes}<small> min</small></strong><span class="muted">Tiempo registrado</span></div><span class="activity-note">${s.length} ${s.length===1?'sesión':'sesiones'}<br><span class="muted">${s.some(x=>x.demo)?'Incluye ejemplo':'Guardadas aquí'}</span></span></div><div class="week-chart" role="img" aria-label="Ejemplo: 32 minutos el jueves, sin actividad los demás días">${['L','M','M','J','V','S','D'].map((d,i)=>`<div class="od-cell ${i===3?'today':''}"><span class="week-track"><span style="--week-height:${i===3?'80%':'6%'}"></span></span><span>${d}</span></div>`).join('')}</div></div><p class="privacy-line">${icon('shield')} Tus datos se quedan en este navegador.</p></div>${navFooter('home')}`;}
function programs(){let list=data.programs.filter(p=>filter==='all'||(filter==='short'?total(p)<=1200:total(p)>1200));return `${topbar('Programas',{action:`<button class="icon-button blue-icon" data-action="new" aria-label="Crear programa">${icon('plus')}</button>`})}<div class="page-scroll od-scroll"><div class="heading-block"><h1 class="page-title" tabindex="-1">Tu forma de<br>entrenar.</h1><p class="intro">Programas que se adaptan a ti.</p></div><div class="segmented" aria-label="Filtrar programas">${[['all','Todos'],['short','Hasta 20 min'],['long','Más de 20 min']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="list-label">MIS PROGRAMAS · ${list.length}</div><div class="list-panel">${list.map(programRow).join('')||`<div class="empty"><h3>${data.programs.length?'Sin programas en este filtro':'Empieza con tu primer programa'}</h3><p>Define tus intervalos y guárdalos para después.</p><button class="btn-pill" data-action="new">Crear programa</button></div>`}</div><button class="add-row od-row" data-action="new">${icon('plus')} Crear un programa</button><div class="open-note od-row-top">${icon('infinity')}<div class="od-field"><strong>El entrenamiento es tuyo.</strong><p class="muted">Personaliza cada intervalo. Consulta todas tus métricas. Sin bloqueos premium en esta propuesta.</p></div></div></div>${navFooter('programs')}`;}
function detail(){const p=program();if(!p){route='programs';return programs();}return `${topbar('Programa',{back:true,action:`<button class="icon-button" data-action="program-menu" aria-label="Opciones del programa">${icon('more')}</button>`})}<div class="page-scroll od-scroll"><div class="heading-block"><h1 class="page-title detail-title" tabindex="-1">${esc(p.name)}</h1><p class="intro">${esc(p.description||'Un programa a tu medida.')}</p></div><div class="detail-stats od-grid" style="--od-cols:3">${stat(fmt(total(p)/60,1),'Duración','min')}${stat(fmt(estimated(p),2),'Distancia aprox.','km')}${stat(p.intervals.length,'Intervalos')}</div><div class="chart-panel">${intervalChart(p.intervals,true)}<div class="chart-axis"><span>Inicio</span><span>${time(total(p))}</span></div><div class="chart-legend"><span><i></i> Esfuerzo</span><span><i class="neutral"></i> Recuperación</span></div></div><button class="device-strip od-row" data-action="device">${icon('bluetooth')}<span class="od-field od-fill"><strong>${data.connected?'Equipo de demo conectado':'Entrenar sin equipo'}</strong><span class="muted">${data.connected?'Conexión simulada':'Puedes probar la sesión igualmente'}</span></span>${icon('arrow','chevron')}</button><div class="section-heading od-row"><h2 class="od-fill">Paso a paso</h2><button class="text-button" data-action="edit">Editar</button></div><ol class="interval-list">${p.intervals.map((x,i)=>`<li class="interval-row od-row"><span class="interval-index ${x.kind==='work'?'effort':''}">${i+1}</span><div class="od-field od-fill"><strong>${kinds[x.kind]}</strong><span class="muted">${fmt(x.speed)} km/h · Inclinación ${x.incline}%</span></div><strong class="od-nowrap">${time(x.seconds)}</strong></li>`).join('')}</ol><p class="fine-print">La velocidad y la inclinación se simulan. No se envían órdenes a equipos físicos.</p></div><footer class="action-footer"><button class="btn-pill full" data-action="start">${icon('play')} Comenzar sesión</button></footer>`;}
function edit(){if(!draft){draft=clone(program()||{id:uid(),name:'Mi programa',description:'Un programa a tu medida.',intervals:[{id:uid(),seconds:120,speed:5,incline:0,kind:'warm'}]});}return `${topbar('Editar programa',{back:true,action:`<button class="text-button" data-action="save-program">Guardar</button>`})}<div class="page-scroll od-scroll"><div class="heading-block"><h1 class="page-title" tabindex="-1">A tu medida.</h1><p class="intro">Cada intervalo, como tú lo necesitas.</p></div><div class="field"><label for="program-name">Nombre del programa (obligatorio)</label><input id="program-name" value="${esc(draft.name)}" maxlength="60" required><p class="field-error" id="name-error" aria-live="polite"></p></div><div class="editor-total od-row"><span class="od-fill">Duración total</span><strong>${time(total(draft))}</strong></div><div class="section-heading od-row"><h2 class="od-fill">Intervalos</h2><span class="muted">${draft.intervals.length} pasos</span></div><div class="editor-list">${draft.intervals.map((x,i)=>`<article class="editor-item"><div class="od-row"><span class="interval-index ${x.kind==='work'?'effort':''}">${i+1}</span><div class="od-field od-fill"><strong>${kinds[x.kind]}</strong><span class="muted">${time(x.seconds)} · ${fmt(x.speed)} km/h · ${x.incline}%</span></div><button class="icon-button" data-interval-edit="${x.id}" aria-label="Editar intervalo ${i+1}">${icon('edit')}</button></div><div class="editor-tools"><button class="icon-button" data-move="${x.id}" data-direction="-1" aria-label="Subir intervalo ${i+1}" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-button" data-move="${x.id}" data-direction="1" aria-label="Bajar intervalo ${i+1}" ${i===draft.intervals.length-1?'disabled':''}>${icon('down')}</button><span class="od-fill"></span><button class="icon-button" data-interval-copy="${x.id}" aria-label="Duplicar intervalo ${i+1}">${icon('copy')}</button><button class="icon-button" data-interval-delete="${x.id}" aria-label="Eliminar intervalo ${i+1}" ${draft.intervals.length===1?'disabled':''}>${icon('trash')}</button></div></article>`).join('')}</div><button class="add-row od-row" data-action="add-interval">${icon('plus')} Añadir intervalo</button></div><footer class="action-footer"><button class="btn-pill full" data-action="save-program">Guardar programa</button></footer>`;}
function session(){const x=running;return `${topbar('Entrenamiento',{action:`<span class="session-demo">SIMULACIÓN</span>`})}<div class="page-scroll od-scroll session-page"><div class="session-heading od-row"><div class="od-field od-fill"><h1 class="page-title" tabindex="-1">${esc(x.name)}</h1><span class="dark-muted" id="phase-position"></span></div><span class="live-pill" id="live-status">En curso</span></div><div class="timer-dial"><svg viewBox="0 0 280 280" width="280" height="280" aria-hidden="true"><circle class="dial-track" cx="140" cy="140" r="128"/><circle class="dial-progress" id="dial-progress" cx="140" cy="140" r="128"/></svg><div class="timer-content od-cell"><span id="phase-name"></span><strong id="phase-timer" class="od-nowrap">00:00</strong><span class="dark-muted" id="elapsed-time"></span></div></div><div class="session-metrics od-grid" style="--od-cols:3">${stat('<span id="live-distance">0,00</span>','Distancia','km')}${stat('<span id="live-calories">0</span>','Energía est.','kcal')}${stat('<span id="live-heart">—</span>','Pulso simulado','lpm')}</div><div class="next-phase od-row"><span class="od-field od-fill"><span class="dark-muted">A continuación</span><strong id="next-name"></strong></span><span class="od-field next-values"><strong id="next-speed"></strong><span class="dark-muted" id="next-duration"></span></span></div><div class="adjustments od-grid" style="--od-cols:2"><div class="adjust-control od-cell"><span>Velocidad <small>km/h</small></span><div class="od-row"><button class="icon-button" data-adjust="speed" data-step="-0.5" aria-label="Reducir velocidad">${icon('minus')}</button><strong id="live-speed">0</strong><button class="icon-button" data-adjust="speed" data-step="0.5" aria-label="Aumentar velocidad">${icon('plus')}</button></div></div><div class="adjust-control od-cell"><span>Inclinación <small>%</small></span><div class="od-row"><button class="icon-button" data-adjust="incline" data-step="-1" aria-label="Reducir inclinación">${icon('minus')}</button><strong id="live-incline">0</strong><button class="icon-button" data-adjust="incline" data-step="1" aria-label="Aumentar inclinación">${icon('plus')}</button></div></div></div><button class="skip-button" data-action="skip">Saltar intervalo ${icon('arrow')}</button></div><footer class="session-footer"><button class="btn-pill pause-button" data-action="pause" id="pause-button">${icon('pause')} Pausar</button><button class="stop-button" data-action="finish" aria-label="Finalizar entrenamiento">${icon('stop')}<span>Finalizar</span></button></footer>`;}
function lineChart(values,label){const safe=values.length?values:[0];const max=Math.max(...safe,1);const points=safe.map((v,i)=>`${i/(safe.length-1||1)*300},${90-v/max*75}`).join(' ');return `<svg class="data-chart" viewBox="0 0 300 104" width="300" height="104" role="img" aria-label="${esc(label)}"><path class="chart-grid-line" d="M0 90H300M0 50H300M0 10H300"/><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function summary(){const s=selectedSession||data.sessions[0];if(!s)return activity();const pace=s.distance>0?Math.round(s.seconds/s.distance):0;return `${topbar('Resumen',{back:true,action:`<button class="icon-button blue-icon" data-action="export" aria-label="Exportar entrenamiento">${icon('download')}</button>`})}<div class="page-scroll od-scroll"><div class="summary-hero"><span class="summary-check">${icon('check')}</span><h1 class="page-title" tabindex="-1">${s.demo?'Cada paso suma.':'Lo hiciste.'}</h1><p class="intro">${esc(s.name)}</p><p class="muted">${date(s.date)} · ${s.demo?'Datos de ejemplo':'Sesión simulada'}</p><div class="distance-display od-nowrap">${fmt(s.distance,2)}<small> km</small></div></div><div class="summary-grid od-grid" style="--od-cols:2">${stat(time(s.seconds),'Tiempo total')}${stat(s.calories,'Energía estimada','kcal')}${stat(pace?time(pace):'—','Ritmo medio','/km')}${stat(s.steps,'Pasos estimados')}</div><section class="metric-section"><div class="od-row"><h2 class="od-fill">Velocidad</h2><span class="muted">km/h</span></div><div class="metric-pair od-grid" style="--od-cols:2">${stat(fmt(s.averageSpeed),'Media')}${stat(fmt(s.maxSpeed),'Máxima')}</div>${lineChart(s.samples,'Velocidad de la sesión en kilómetros por hora')}<div class="chart-axis"><span>00:00</span><span>${time(s.seconds)}</span></div></section><section class="metric-section"><div class="od-row"><h2 class="od-fill">Frecuencia cardíaca</h2><span class="muted">lpm</span></div><div class="metric-pair od-grid" style="--od-cols:2">${stat(s.heart,'Media simulada')}${stat(s.maxHeart,'Máxima simulada')}</div>${lineChart(s.samples.map(v=>Math.round(95+v*5.5)),'Perfil cardíaco ilustrativo, no una lectura de sensor')}</section><p class="fine-print">${s.demo?'Resumen de referencia basado en la captura de FitShow. Las curvas son ilustrativas.':'Las métricas se generan para demostrar la interfaz; no provienen de un sensor.'}</p><button class="btn-pill full" data-action="export">${icon('download')} Exportar datos</button></div><footer class="action-footer"><button class="btn-secondary full" data-nav="activity">Ver actividad</button></footer>`;}
function activity(){return `${topbar('Actividad')}<div class="page-scroll od-scroll"><div class="heading-block"><h1 class="page-title" tabindex="-1">Tu constancia,<br>en perspectiva.</h1><p class="intro">Cada sesión tiene su historia.</p></div><div class="activity-totals od-grid" style="--od-cols:2">${stat(data.sessions.length,'Sesiones guardadas')}${stat(fmt(data.sessions.reduce((s,x)=>s+x.distance,0),2),'Distancia total','km')}</div><div class="section-heading od-row"><h2 class="od-fill">Historial</h2><span class="muted">En este dispositivo</span></div><div class="list-panel">${data.sessions.map(s=>`<button class="history-row" data-session="${esc(s.id)}"><span class="od-row"><span class="history-symbol">${icon('run')}</span><span class="od-field od-fill"><strong class="od-truncate">${esc(s.name)}</strong><span class="muted">${date(s.date)} · ${s.demo?'Ejemplo':'Simulación'}</span></span>${icon('arrow','chevron')}</span><span class="history-numbers"><strong>${fmt(s.distance,2)} <small>km</small></strong><span>${time(s.seconds)}</span><span>${s.calories} kcal</span></span></button>`).join('')||`<div class="empty">${icon('activity')}<h3>Tu historia empieza con una sesión.</h3><p>Elige un programa. Al terminar, verás aquí tu resumen.</p><button class="btn-pill" data-nav="programs">Explorar programas</button></div>`}</div><p class="privacy-line">${icon('shield')} Historial local. Sin cuenta ni nube.</p></div>${navFooter('activity')}`;}
function settings(){return `${topbar('Ajustes')}<div class="page-scroll od-scroll"><div class="heading-block"><h1 class="page-title" tabindex="-1">Tú decides.</h1><p class="intro">Tu equipo, tus datos, tu entrenamiento.</p></div><div class="list-label">EQUIPO</div><div class="list-panel"><button class="setting-row od-row" data-action="device">${icon('bluetooth')}<span class="od-field od-fill"><strong>Conexión del equipo</strong><span class="muted">${data.connected?'Conectado · Simulación':'Sin conexión · Modo de demostración'}</span></span>${icon('arrow','chevron')}</button><div class="setting-row od-row"><span class="od-field od-fill"><strong>Unidades</strong><span class="muted">Distancia, velocidad y elevación</span></span><span>km · km/h · %</span></div></div><div class="list-label">TUS DATOS</div><div class="list-panel"><div class="setting-row od-row"><span class="od-field od-fill"><strong>Almacenamiento local</strong><span class="muted">${storageAvailable?'Los cambios se guardan en este navegador.':'Disponible solo durante esta visita.'}</span></span>${icon(storageAvailable?'shield':'activity')}</div><button class="setting-row od-row danger-text" data-action="clear-history"><span class="od-fill">Borrar historial</span>${icon('trash')}</button></div><div class="about-block"><span class="about-logo"><img class="brand-mark brand-mark-large" src="./assets/vagancia-fitness-mark.svg" width="96" height="96" alt="Símbolo de VAGANCIA FITNESS: anillo abierto con pulso"></span><h2>VAGANCIA FITNESS</h2><p>Una propuesta independiente para entrenar con más claridad y control.</p><p class="muted">Concepto de interfaz para una alternativa de código abierto. Sin afiliación con FitShow ni Apple.</p><span class="version">PROTOTIPO · VERSIÓN 0.1</span><p class="fine-print">La conectividad real y la licencia de distribución del proyecto siguen pendientes de definición.</p></div></div>${navFooter('settings')}`;}
function render(){const currentScroll=route===lastRenderedRoute?($('.page-scroll')?.scrollTop||0):0;lastRenderedRoute=route;const dark=route==='session';document.documentElement.classList.toggle('training-mode',dark);app.className=`app od-screen ${dark?'training':''}`;const views={home,programs,detail,edit,session,summary,activity,settings};app.innerHTML=(views[route]||home)();if($('.page-scroll'))$('.page-scroll').scrollTop=currentScroll;if(dark)updateLive();}
function openSheet(title,content){const layer=$('#sheet-layer');if(!layer.contains(document.activeElement))sheetFocus=document.activeElement;layer.innerHTML=`<div class="sheet-scrim" data-action="close-sheet"></div><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-heading od-row"><h2 class="od-fill" id="sheet-title">${title}</h2><button class="icon-button" data-action="close-sheet" aria-label="Cerrar">${icon('close')}</button></div>${content}</section>`;layer.hidden=false;app.inert=true;$('.sheet')?.focus();}
function closeSheet(){const layer=$('#sheet-layer');layer.hidden=true;layer.innerHTML='';app.inert=false;sheetFocus?.isConnected&&sheetFocus.focus();if(sheetResumeState!==null&&running){running.paused=sheetResumeState;running.lastTick=performance.now();updateLive();}sheetResumeState=null;}
function deviceSheet(){openSheet('Tu equipo',`<p class="intro">Prueba el flujo de conexión con un equipo de demostración.</p><div class="device-preview od-row">${icon('bluetooth')}<div class="od-field od-fill"><strong>Cinta de demostración</strong><span class="muted">${data.connected?'Conectada · Sin Bluetooth real':'Equipo simulado · Disponible'}</span></div></div><p class="fine-print">No se realiza una búsqueda Bluetooth ni se controla ninguna máquina.</p><button class="btn-pill full" data-action="toggle-device">${data.connected?'Desconectar demo':'Conectar demo'}</button>`);}
function intervalSheet(id){const x=id?draft.intervals.find(y=>y.id===id):{seconds:90,speed:8,incline:0,kind:'work'};openSheet(id?'Editar intervalo':'Nuevo intervalo',`<form id="interval-form" data-id="${id||''}" novalidate><p class="fine-print" style="margin:0 0 16px">Todos los campos son obligatorios.</p><div id="interval-errors" class="field-error" aria-live="polite"></div><div class="field"><label for="interval-kind">Tipo de intervalo</label><select id="interval-kind" name="kind">${Object.entries(kinds).map(([v,n])=>`<option value="${v}" ${x.kind===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="interval-seconds">Duración en segundos</label><input id="interval-seconds" name="seconds" type="number" inputmode="numeric" min="15" max="3600" step="1" value="${x.seconds}" aria-describedby="seconds-help"><p class="field-help" id="seconds-help">De 15 a 3600 segundos. 90 s = 1 min 30 s.</p></div><div class="od-grid" style="--od-cols:2"><div class="field"><label for="interval-speed">Velocidad · km/h</label><input id="interval-speed" name="speed" type="number" inputmode="decimal" min="1" max="20" step="0.1" value="${x.speed}" aria-describedby="speed-help"><p class="field-help" id="speed-help">De 1 a 20 km/h.</p></div><div class="field"><label for="interval-incline">Inclinación · %</label><input id="interval-incline" name="incline" type="number" inputmode="numeric" min="0" max="15" step="1" value="${x.incline}" aria-describedby="incline-help"><p class="field-help" id="incline-help">De 0 a 15%.</p></div></div><button class="btn-pill full" type="submit">${id?'Guardar intervalo':'Añadir intervalo'}</button></form>`);}
function captureDraft(){if($('#program-name'))draft.name=$('#program-name').value;}
function saveProgram(){captureDraft();if(!draft.name.trim()){const field=$('#program-name');$('#name-error').textContent='Escribe un nombre para guardar el programa.';field.setAttribute('aria-invalid','true');field.focus();return;}draft.name=draft.name.trim();const found=data.programs.findIndex(p=>p.id===draft.id);if(found>=0)data.programs[found]=clone(draft);else data.programs.push(clone(draft));selectedId=draft.id;draft=null;persist();navigate('detail');toast('Programa guardado en este navegador.');}
function beginSession(){const p=program();if(!p)return;running={name:p.name,intervals:clone(p.intervals),index:0,phaseElapsed:0,elapsed:0,distance:0,calories:0,heart:0,samples:[],paused:false,speed:p.intervals[0].speed,incline:p.intervals[0].incline,lastTick:performance.now()};navigate('session');}
function updateLive(){if(route!=='session'||!running)return;const x=running,phase=x.intervals[x.index],next=x.intervals[x.index+1];$('#phase-name').textContent=x.paused?'En pausa':kinds[phase.kind];$('#phase-timer').textContent=time(Math.max(0,phase.seconds-Math.floor(x.phaseElapsed)));$('#phase-position').textContent=`Intervalo ${x.index+1} de ${x.intervals.length}`;$('#elapsed-time').textContent=`${time(Math.floor(x.elapsed))} transcurridos`;$('#live-status').textContent=x.paused?'En pausa':'En curso';$('#live-distance').textContent=fmt(x.distance,2);$('#live-calories').textContent=Math.floor(x.calories);$('#live-heart').textContent=x.elapsed>1?Math.round(x.heart):'—';$('#live-speed').textContent=fmt(x.speed);$('#live-incline').textContent=x.incline;$('#next-name').textContent=next?kinds[next.kind]:'Fin de la sesión';$('#next-speed').textContent=next?`${fmt(next.speed)} km/h`:'Buen trabajo';$('#next-duration').textContent=next?time(next.seconds):'';$('#dial-progress').style.strokeDashoffset=804*(1-x.phaseElapsed/phase.seconds);$('#pause-button').innerHTML=`${icon(x.paused?'play':'pause')} ${x.paused?'Continuar':'Pausar'}`;}
function advance(){const x=running;if(x.index>=x.intervals.length-1){finishSession();return;}x.index++;x.phaseElapsed=0;x.speed=x.intervals[x.index].speed;x.incline=x.intervals[x.index].incline;toast(`Comienza: ${kinds[x.intervals[x.index].kind]}`);updateLive();}
function finishSession(){if(!running)return;const x=running,seconds=Math.max(1,Math.round(x.elapsed));const record={id:uid(),name:x.name,date:new Date().toISOString(),seconds,distance:x.distance,calories:Math.floor(x.calories),steps:Math.floor(x.distance*1250),heart:x.samples.length?Math.round(x.samples.reduce((a,b)=>a+b,0)/x.samples.length*5.5+95):0,maxHeart:x.samples.length?Math.round(Math.max(...x.samples)*5.5+95):0,averageSpeed:x.distance/seconds*3600,maxSpeed:Math.max(...x.samples,0),demo:false,samples:x.samples.length?x.samples:[0]};data.sessions.unshift(record);selectedSession=record;running=null;persist();closeSheet();navigate('summary');toast('Sesión simulada guardada.');}
function downloadSession(){const s=selectedSession||data.sessions[0];if(!s)return;const payload={application:'VAGANCIA FITNESS',simulation:true,units:{distance:'km',speed:'km/h',heartRate:'bpm'},...s};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`vagancia-fitness-${s.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Datos de la sesión exportados.');}
const actions={
 back(){if(route==='edit'){captureDraft();openSheet('¿Salir sin guardar?',`<p>Los cambios de este programa se descartarán.</p><div class="sheet-actions"><button class="btn-pill full" data-action="close-sheet">Seguir editando</button><button class="btn-secondary full" data-action="discard-edit">Descartar cambios</button></div>`);}else if(route==='detail')navigate('programs',{back:true});else if(route==='summary')navigate('activity',{back:true});else navigate(lastPage==='session'?'home':lastPage,{back:true});},
 'discard-edit'(){closeSheet();draft=null;navigate(program()?'detail':'programs',{back:true});},
 new(){draft={id:uid(),name:'Mi programa',description:'Un programa a tu medida.',intervals:[{id:uid(),seconds:120,speed:5,incline:0,kind:'warm'}]};navigate('edit');},
 edit(){draft=clone(program());navigate('edit');},'save-program':saveProgram,'add-interval'(){captureDraft();intervalSheet();},device:deviceSheet,
 'toggle-device'(){data.connected=!data.connected;persist();closeSheet();render();toast(data.connected?'Equipo de demo conectado.':'Equipo de demo desconectado.');},
 'close-sheet':closeSheet,
 'program-menu'(){openSheet('Opciones del programa',`<div class="menu-list"><button data-action="menu-edit">${icon('edit')} Editar programa</button><button data-action="copy-program">${icon('copy')} Duplicar programa</button><button class="danger-text" data-action="confirm-delete-program">${icon('trash')} Eliminar programa</button></div>`);},
 'menu-edit'(){closeSheet();actions.edit();},
 'copy-program'(){const p=clone(program());p.id=uid();p.name=`${p.name} (copia)`;p.intervals.forEach(x=>x.id=uid());data.programs.push(p);selectedId=p.id;persist();closeSheet();render();toast('Programa duplicado.');},
 'confirm-delete-program'(){openSheet('¿Eliminar este programa?',`<p>Se eliminará “${esc(program().name)}”. Tu historial se conservará.</p><div class="sheet-actions"><button class="btn-danger full" data-action="delete-program">Eliminar programa</button><button class="btn-secondary full" data-action="close-sheet">Cancelar</button></div>`);},
 'delete-program'(){data.programs=data.programs.filter(p=>p.id!==selectedId);selectedId=data.programs[0]?.id;persist();closeSheet();navigate('programs');toast('Programa eliminado.');},
 start:beginSession,
 pause(){running.paused=!running.paused;running.lastTick=performance.now();updateLive();},
 skip:advance,
 finish(){const wasPaused=running.paused;running.paused=true;openSheet('¿Finalizar la sesión?',`<p>Tu progreso se guardará en Actividad.</p><div class="sheet-actions"><button class="btn-pill full" data-action="save-session">Finalizar y guardar</button><button class="btn-secondary full" data-action="resume-session" data-was-paused="${wasPaused}">Volver al entrenamiento</button></div>`);sheetResumeState=wasPaused;updateLive();},
 'save-session':finishSession,
 'resume-session'(){closeSheet();running.lastTick=performance.now();updateLive();},
 export:downloadSession,
 'clear-history'(){openSheet('¿Borrar el historial?',`<p>Se eliminarán ${data.sessions.length} sesiones de este navegador. Esta acción no se puede deshacer.</p><div class="sheet-actions"><button class="btn-danger full" data-action="delete-history">Borrar historial</button><button class="btn-secondary full" data-action="close-sheet">Cancelar</button></div>`);},
 'delete-history'(){data.sessions=[];persist();closeSheet();render();toast('Historial borrado.');}
};
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b||b.disabled)return;
 if(b.dataset.nav){navigate(b.dataset.nav);return;}
 if(b.dataset.program){selectedId=b.dataset.program;navigate('detail');return;}
 if(b.dataset.session){selectedSession=data.sessions.find(s=>s.id===b.dataset.session);navigate('summary');return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.intervalEdit){captureDraft();intervalSheet(b.dataset.intervalEdit);return;}
 if(b.dataset.intervalCopy){captureDraft();const i=draft.intervals.findIndex(x=>x.id===b.dataset.intervalCopy);const x=clone(draft.intervals[i]);x.id=uid();draft.intervals.splice(i+1,0,x);render();toast('Intervalo duplicado.');return;}
 if(b.dataset.intervalDelete){captureDraft();draft.intervals=draft.intervals.filter(x=>x.id!==b.dataset.intervalDelete);render();return;}
 if(b.dataset.move){captureDraft();const i=draft.intervals.findIndex(x=>x.id===b.dataset.move),j=i+Number(b.dataset.direction);if(j>=0&&j<draft.intervals.length)[draft.intervals[i],draft.intervals[j]]=[draft.intervals[j],draft.intervals[i]];render();return;}
 if(b.dataset.adjust&&running){const key=b.dataset.adjust;running[key]=Math.round(Math.max(key==='speed'?1:0,Math.min(key==='speed'?20:15,running[key]+Number(b.dataset.step)))*10)/10;updateLive();return;}
 const action=b.dataset.action;if(action&&actions[action])actions[action]();
});
function validateField(field){const valid=field.value.trim()!==''&&field.validity.valid;field.setAttribute('aria-invalid',String(!valid));let error=field.parentElement.querySelector('.input-error');if(!valid){if(!error){error=document.createElement('p');error.className='input-error field-error';error.id=field.id+'-error';field.parentElement.appendChild(error);field.setAttribute('aria-describedby',(field.getAttribute('aria-describedby')||'')+' '+error.id);}error.textContent=field.name==='seconds'?'Usa un número entero de 15 a 3600.':field.name==='speed'?'Usa un valor de 1 a 20, con un decimal.':'Usa un número entero de 0 a 15.';}else error?.remove();return valid;}
document.addEventListener('focusout',e=>{if(e.target.matches('#interval-form input'))validateField(e.target);if(e.target.id==='program-name'&&draft){captureDraft();$('#name-error').textContent=draft.name.trim()?'':'Escribe un nombre para el programa.';}});
document.addEventListener('submit',e=>{if(e.target.id!=='interval-form')return;e.preventDefault();const form=e.target;const fields=[...form.querySelectorAll('input')];const invalid=fields.filter(f=>!validateField(f));if(invalid.length){$('#interval-errors').innerHTML=`Revisa los campos: ${invalid.map(f=>`<a href="#${f.id}" data-error-target="${f.id}">${f.labels[0].textContent}</a>`).join(', ')}.`;invalid[0].focus();return;}const v=new FormData(form);const entry={id:form.dataset.id||uid(),seconds:Number(v.get('seconds')),speed:Number(v.get('speed')),incline:Number(v.get('incline')),kind:v.get('kind')};if(form.dataset.id)draft.intervals[draft.intervals.findIndex(x=>x.id===entry.id)]=entry;else draft.intervals.push(entry);closeSheet();render();toast('Intervalo guardado.');});
document.addEventListener('click',e=>{const a=e.target.closest('[data-error-target]');if(a){e.preventDefault();$('#'+a.dataset.errorTarget)?.focus();}});
document.addEventListener('keydown',e=>{const layer=$('#sheet-layer');if(layer.hidden)return;if(e.key==='Escape'){e.preventDefault();closeSheet();return;}if(e.key==='Tab'){const nodes=[...layer.querySelectorAll('button,input,select,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('sheet'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
setInterval(()=>{if(!running)return;const now=performance.now();const delta=Math.max(0,(now-running.lastTick)/1000);running.lastTick=now;if(running.paused)return;let remaining=delta;while(remaining>0&&running){const x=running;const slice=Math.min(remaining,x.intervals[x.index].seconds-x.phaseElapsed);x.phaseElapsed+=slice;x.elapsed+=slice;x.distance+=x.speed*slice/3600;x.calories+=x.speed*slice/52;x.heart=95+x.speed*5.5+Math.sin(x.elapsed/8)*3;if(Math.floor(x.elapsed)%3===0&&x.samples.length<Math.floor(x.elapsed/3)+1)x.samples.push(x.speed);remaining-=slice;if(x.phaseElapsed>=x.intervals[x.index].seconds)advance();if(slice===0&&remaining>0)break;}updateLive();},250);
render();
